def text_of(s): return '\n\n'.join(s['paragraphs'])
def mk(s,new,reviews,ids,speed=False):
    q,a=base.qa(s['items'],ids); text=text_of(s)
    return {'id':s['id'],'language':'fr','cefr':'B2','unit':2,'sequence':s['sequence'],'revision':1,'title':s['title'],'passage_type':s['ptype'],'genre':s['genre'],'domains':s['domains'],'topics':s['topics'],'text':text,'word_count':len(text.split()),'sentence_count':max(1,len(re.findall(r'[.!?](?:[»”"])?',text))),'estimated_known_token_coverage':0,'new_lexical_targets':new,'review_lexical_targets':reviews,'grammar_targets':s['grammar'],'discourse_targets':s['discourse'],'questions':q,'answer_key':a,'speed_training':{'timed':speed,'benchmark_eligible':speed,'comprehension_gate':0.8,'new_word_policy':'none' if speed else 'controlled','notes':'French B2 Unit 02 guarded production batch.'},'quality':{'status':'draft','schema_check':'pending','linguistic_review':'pending','pedagogical_review':'pending','answer_key_check':'pending','coverage_check':'pending','fact_check':'not_required','notes':['Guarded French B2 Unit 02: decision under uncertainty.','Accepted B2 default of four fresh targets per P01-P05; P06 zero new.']},'paired_text_group':None,'prerequisites':['French B2 Unit 01 accepted calibration'],'difficulty_notes_internal':'B2 uncertainty reasoning: commitment thresholds, severity vs certainty, information status, scenario robustness and reversible experimental decisions.','reader_tags':['unit_role:'+s['ptype'],'generation_batch','french_b2_u02']}

def build(a1,a2,b1,b2,deck):
    prior=base.prior(a1+a2+b1+b2); prior_ids={t.get('id') for r in a1+a2+b1+b2 for t in r.get('new_lexical_targets',[]) if isinstance(t,dict)}; prior_forms={t.get('form') for r in a1+a2+b1+b2 for t in r.get('new_lexical_targets',[]) if isinstance(t,dict)}; bad=[]
    for f in FORMS:
        if f not in deck: bad.append(f+':missing_lexicon')
        elif base.tid(deck[f]['rank']) in prior_ids or f in prior_forms or prior.get(f): bad.append(f+':already_deliberate')
    if bad: raise AssertionError('B2 Unit02 candidate failures: '+', '.join(bad))
    out=[]
    for s in SPECS:
        text=text_of(s); new=[base.nt(f,text,deck) for f in s['forms']]; reviews=[base.rev(f,prior) for f in s['reviews']]; ids={t['form']:t['id'] for t in new+reviews}; out.append(mk(s,new,reviews,ids))
    reviews=[base.cur(f,deck) for f in FORMS]; ids={t['form']:t['id'] for t in reviews}; out.append(mk(CHECKPOINT,[],reviews,ids,True)); return out

def main():
    for label,path in [('A1',A1),('A2',A2),('B1',B1),('B2',CANON)]:
        got=subprocess.check_output(['git','hash-object',str(path)],text=True).strip()
        if got!=EXPECTED[label]: raise AssertionError(f'{label} blob drift: {got} != {EXPECTED[label]}')
    a1=[json.loads(x) for x in A1.read_text(encoding='utf-8').splitlines() if x.strip()]; a2=[json.loads(x) for x in A2.read_text(encoding='utf-8').splitlines() if x.strip()]; b1=[json.loads(x) for x in B1.read_text(encoding='utf-8').splitlines() if x.strip()]; b2=[json.loads(x) for x in CANON.read_text(encoding='utf-8').splitlines() if x.strip()]
    if len(b2)!=6 or b2[-1]['id']!='fr-b2-u01-p06': raise AssertionError('unexpected B2 prerequisite frontier')
    deck=base.deck(); unit=build(a1,a2,b1,b2,deck); V=Draft202012Validator(json.loads(SCHEMA.read_text(encoding='utf-8')))
    prior_ids={t.get('id') for r in a1+a2+b1+b2 for t in r.get('new_lexical_targets',[]) if isinstance(t,dict)}; prior_forms={t.get('form') for r in a1+a2+b1+b2 for t in r.get('new_lexical_targets',[]) if isinstance(t,dict)}; newids=[];newforms=[]
    if [r['sequence'] for r in unit]!=list(range(7,13)) or [r['id'] for r in unit]!=[f'fr-b2-u02-p{i:02d}' for i in range(1,7)]: raise AssertionError('B2 Unit02 sequence/id continuity failure')
    for r in unit:
        errs=sorted(V.iter_errors(r),key=lambda e:list(e.path))
        if errs: raise AssertionError(f"{r['id']}: schema {[e.message for e in errs[:8]]}")
        if not 350<=r['word_count']<=550: raise AssertionError(f"{r['id']}: B2 word band {r['word_count']}")
        if len(r['questions'])!=10 or len(r['answer_key'])!=10: raise AssertionError(f"{r['id']}: assessment count")
        if r['sequence']<=11 and len(r['new_lexical_targets'])!=4: raise AssertionError(f"{r['id']}: accepted B2 default load must be 4")
        if r['sequence']==12 and r['new_lexical_targets']: raise AssertionError('B2 Unit02 P06 must have zero new targets')
        amap={a['question_id']:a['id'] for a in r['answer_key']}; local={t['id'] for fld in ('new_lexical_targets','review_lexical_targets') for t in r.get(fld,[]) if isinstance(t,dict)}
        for q in r['questions']:
            if amap.get(q['id'])!=q['answer_id'] or any(tid not in local for tid in q.get('target_ids',[])): raise AssertionError(f"{r['id']} {q['id']}: linkage/target declaration")
        for t in r['new_lexical_targets']:
            src=deck.get(t['form'])
            if t['id'] in prior_ids or t['form'] in prior_forms or not src or t['source_rank']!=src['rank'] or t['id']!=base.tid(src['rank']) or base.cnt(r['text'],t['form'])!=t['exposures_in_text']: raise AssertionError(f"{r['id']}: source/exposure/freshness drift {t}")
            newids.append(t['id']); newforms.append(t['form'])
        for t in r['review_lexical_targets']:
            if t['representation'] in {'running_text','summary'} and base.cnt(r['text'],t['form'])<1: raise AssertionError(f"{r['id']}: invisible review {t['form']}")
    if len(newids)!=20 or len(set(newids))!=20 or len(set(newforms))!=20: raise AssertionError('B2 Unit02 lexical uniqueness failure')
    CANON.write_text(''.join(json.dumps(r,ensure_ascii=False,sort_keys=True)+'\n' for r in b2+unit),encoding='utf-8')
    print(json.dumps({'status':'PASS','level':'B2','unit':2,'appended_passages':6,'b2_passages':12,'questions':60,'answers':60,'new_targets':20,'word_counts':{r['id']:r['word_count'] for r in unit},'targets':[{'form':f,'rank':deck[f]['rank'],'id':base.tid(deck[f]['rank'])} for f in FORMS]},ensure_ascii=False))

if __name__=='__main__': main()
